import { useState, useEffect } from "react";
import "./index.scss";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faDiscord, faGithub, faLinkedin } from "@fortawesome/free-brands-svg-icons";

const SECTION_IDS = ["about", "portfolio", "contact"];

const Sidebar = () => {
  const [activeSection, setActiveSection] = useState("");

  // Scroll spy: track which section is in view
  useEffect(() => {
    const handleScroll = () => {
      const offset = 90; // height of the header

      let current = "";
      SECTION_IDS.forEach((id) => {
        const el = document.getElementById(id);
        if (!el) return;

        const rect = el.getBoundingClientRect();
        const top = rect.top;
        const bottom = rect.bottom;

        if (top <= offset + 10 && bottom > offset + 10) {
          current = id;
        }
      });

      setActiveSection(current);
    };

    handleScroll(); // run once on mount
    window.addEventListener("scroll", handleScroll);
    window.addEventListener("resize", handleScroll);

    return () => {
      window.removeEventListener("scroll", handleScroll);
      window.removeEventListener("resize", handleScroll);
    };
  }, []);

  const scrollToSection = (id) => (e) => {
    e.preventDefault();
    const el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    }
  };

  return (
    <header className="nav-bar">
      {/* Left: name/brand */}
      <div className="brand">
        <span className="brand-name">Chris Capizzuto</span>
      </div>

      {/* Center: HTML-style section links */}
      <nav>
        <a
          href="#about"
          onClick={scrollToSection("about")}
          className={`nav-link ${activeSection === "about" ? "active" : ""}`}
        >
          &lt;About&gt;
        </a>
        <a
          href="#portfolio"
          onClick={scrollToSection("portfolio")}
          className={`nav-link ${activeSection === "portfolio" ? "active" : ""}`}
        >
          &lt;Portfolio&gt;
        </a>
        <a
          href="#contact"
          onClick={scrollToSection("contact")}
          className={`nav-link ${activeSection === "contact" ? "active" : ""}`}
        >
          &lt;Contact&gt;
        </a>
      </nav>

      {/* Right: socials */}
      <ul>
        <li>
          <a
            target="_blank"
            rel="noreferrer"
            href="https://www.linkedin.com/?original_referer="
          >
            <FontAwesomeIcon icon={faLinkedin} />
          </a>
        </li>
        <li>
          <a target="_blank" rel="noreferrer" href="https://www.github.com">
            <FontAwesomeIcon icon={faGithub} />
          </a>
        </li>
        <li>
          <a target="_blank" rel="noreferrer" href="https://www.discord.com">
            <FontAwesomeIcon icon={faDiscord} />
          </a>
        </li>
      </ul>
    </header>
  );
};

export default Sidebar;
